typedef enum { OP_CONST, OP_ADD, OP_GET } op_kind;
struct node { op_kind kind; union {
    double c; struct { struct node *l, *r; } b; const char *key; } u; };

double eval(const struct node *n, struct env *e) {
    switch (n->kind) {
    case OP_CONST: return n->u.c;
    case OP_ADD:   return eval(n->u.b.l, e) + eval(n->u.b.r, e);
    case OP_GET:   return env_get(e, n->u.key);
    }
    return 0; /* unreachable for a well-formed program */
}
